cases=[];grades=[]
def add(title,domain,prompt,criteria,files=None,web=False):
 i=len(cases)+1; ident=f'complex-{i:02d}'
 fixtures={p:dict(encoding='utf8',content=s,sha256=hashlib.sha256(s.encode()).hexdigest()) for p,s in (files or {}).items()}
 cases.append(dict(id=ident,domain=domain,family=ident,split='validation',variant=i,prompt=prompt+'\n\nGive a complete, auditable answer, including calculations or executable code where requested. Separate facts, assumptions and unresolved evidence. Do not modify workspace files.',history=[],files=fixtures,execution=dict(effort='low',deadlineMs=600000,writes=False,web=web,media=False),comparison='answer'))
 grades.append(dict(id=ident,title=title,criteria=[dict(id=f'C{j+1}',weight=20,requirement=c) for j,c in enumerate(criteria)],scoring='0=absent/wrong;10=partly correct with material omission;20=complete and supported. Five criteria sum100. Citation claims require retrieved evidence. Errors do not erase demonstrated partial credit.'))
