apps=[('custody','FrostLedger','A local cold-chain shipment custody and excursion investigation dashboard.',[
('F01','Two seeded organizations North and South; hashed-password login/logout with server-side session cookies; viewer/operator/admin roles.'),
('F02','All shipment, reading, incident and export routes enforce tenant membership from the session; reject guessed cross-tenant IDs.'),
('F03','Create shipments with unique tenant-local reference, origin,destination and integer min/max temperature in tenths Celsius; require min<max.'),
('F04','List shipments with reference search,status filter,stable pagination and meaningful empty states.'),
('F05','Append custody transitions created->in_transit->delivered, with actor,time and location; reject backwards or skipped transitions.'),
('F06','Import JSON temperature readings with immutable eventId,timestamp and integer temperature; duplicate identical events are no-ops; conflicting duplicate payload returns409 atomically.'),
('F07','Accept out-of-order timestamps; recompute excursions as consecutive out-of-range samples in timestamp order; readings exactly at min/max are in-range.'),
('F08','Show a timeline/chart and an accessible equivalent table; each excursion indicates start/end and maximum deviation without inventing continuous measurements.'),
('F09','Operators open and resolve incidents with a required resolution note; retain chronological audit history.'),
('F10','Viewer can read but cannot mutate; admin can manage local users without removing the final admin.'),
('F11','CSV export obeys current filters, quotes correctly and neutralizes formula-leading customer text; no password/session fields.'),
('F12','Dashboard counts derive from current tenant data; data survives server restart; invalid batches leave no partial writes.')],
'''Required API (JSON): GET /health -> {ok:true}; POST /api/login {email,password}; POST /api/logout; GET /api/me; GET/POST /api/shipments; GET /api/shipments/:id; POST /api/shipments/:id/transitions {status,location}; POST /api/shipments/:id/readings {readings:[{eventId,timestamp,temperature}]}; GET /api/shipments/:id/readings; GET /api/shipments/:id/excursions; GET /api/shipments/export.csv. Create input {reference,origin,destination,minTemperature,maxTemperature}. Return created entities with id; lists as {items,total}. Use400 validation,401 unauthenticated,403 role denial,404 cross-tenant/notfound,409 conflicts. timestamps ISO8601 UTC; reject malformed dates. Excursion list {items:[{start,end,sampleCount,maxDeviation}]}; isolated violating sample has identical start/end. Seed a shipment reference SOUTH-ONLY in South. North temperature test min20,max80; readings 00:00 temp50,00:01 temp10,00:02 temp90,00:03 temp80 -> one excursion,2samples,start00:01,end00:02,maxDeviation10.'''),
('workshop','BenchHarbor','A local shared workshop booking, maintenance and consumable-inventory web application.',[
('F01','Two seeded organizations Birch and Pine; hashed-password session login/logout and member/manager roles.'),
('F02','Server-enforced tenant scoping on resources,bookings,maintenance,inventory and CSV; never trust client role/tenant fields.'),
('F03','Managers create resources with name and positive integer capacity; list/search/archive without deleting booking history.'),
('F04','Members book a resource over half-open UTC intervals [start,end); duration15minutes..8hours, integer seats1..capacity, nonempty purpose.'),
('F05','Concurrent reservations must not exceed capacity at ANY instant; touching endpoints do not overlap; enforce transactionally.'),
('F06','Idempotency-Key is required for booking creation, scoped to user: same payload replays same booking, changed payload returns409.'),
('F07','Members cancel own future bookings; managers cancel any with an audit note; cancellations release capacity.'),
('F08','Managers add maintenance blocks that reject overlaps with active bookings; blocks prevent future bookings, with clear conflict feedback.'),
('F09','Manager-only consumable stock adjustments use signed integers and immutable movement IDs; duplicates no-op, conflicts409, stock cannot become negative.'),
('F10','Calendar and accessible list views share the same data; filters by resource/date/status and mobile layout preserve actions.'),
('F11','Member cannot edit capacity,maintenance or inventory; all sensitive operations have actor/time audit entries.'),
('F12','Dashboard uses persisted counts/stock; safe filtered CSV export, clear invalid/loading/empty/success states, restart persistence.')],
'''Required API(JSON): GET /health ->{ok:true}; POST /api/login {email,password}; POST /api/logout; GET /api/me; GET/POST /api/resources; GET /api/resources/:id; POST /api/bookings with Idempotency-Key and {resourceId,start,end,seats,purpose}; GET /api/bookings ->{items,total}; POST /api/bookings/:id/cancel {note}; POST /api/maintenance {resourceId,start,end,note}; GET /api/maintenance; POST /api/inventory/items {name}; POST /api/inventory/items/:id/movements {movementId,quantity,note}; GET /api/inventory/items; GET /api/bookings/export.csv. Created entities return id; lists {items,total}; inventory item includes quantity. Status400 validation,401 unauthenticated,403 role,404 cross-tenant/notfound,409 conflict. Server configurable NOW for deterministic test clock (default real clock); tests use2033-01-01T00:00:00Z and bookings2033-01-02. Seed resource PINE-ONLY in Pine.''')]
appcases=[];appgrades=[]
for i,(slug,name,description,features,api) in enumerate(apps,1):
 ident=f'build-{i:02d}-{slug}'
 orgs=('North','South') if i==1 else ('Birch','Pine')
 role='admin' if i==1 else 'manager';other='operator' if i==1 else 'member';readonly='viewer' if i==1 else 'member'
 text=f'''# RFP: {name}\n\n{description}\n\nBuild a complete local web app in this initially empty workspace: Node22 backend, SQLite persistence, and a real browser UI (framework choice is yours). No external services, accounts, paid APIs or Docker required. Use fictitious data. Backend defaults to127.0.0.1 with configurable PORT.\n\n## Features\n'''+''.join(f'- {fid}: {req}\n' for fid,req in features)+f'''\n## API contract\n{api}\n\n## Reproducible delivery\nProvide package.json scripts: npm run setup (initialize DB and idempotently seed), npm run build, npm start, npm test. DATABASE_PATH selects a fresh SQLite file; APP_PORT or PORT selects port. npm start serves both UI and API. README must explain exact commands. Include delivery.json with actual limitations and tested commands, never fabricated success. Do not change RFP.md or ENVIRONMENT.md.\n\nSeed these demo accounts, all password `Demo-Forest-731!`, stored only as password hashes: {role}@{orgs[0].lower()}.test, {other}@{orgs[0].lower()}.test, {readonly}@{orgs[0].lower()}.test, {role}@{orgs[1].lower()}.test. Where two addresses coincide, one account suffices. Seed at least12 realistic records across both organizations. Login inputs must have accessible labels Email and Password; submit button Sign in. Show current organization and user role. Logout must invalidate the server session.\n\n## Quality and security\nUse parameterized SQL; strict payload/type validation; no mass assignment or unsafe HTML; safe cookies and CSRF/origin protection for browser mutations; bounded request sizes. Time intervals use validated UTC instants. Document demo-only security assumptions. Every visible control must work. Keyboard focus, labels, table headers, contrast, responsive layout at390px and1280px, and durable error feedback matter. Include meaningful domain and authorization tests. Test restart persistence and concurrency; do not replace tests with file-existence assertions.\n\n## Completion\nImplement end to end, execute builds/tests, and leave source plus generated build output. No follow-up instructions or evaluator repairs will be supplied. Clearly state any missing feature or environment failure.\n'''
 (root/'rfps'/f'{ident}.md').write_text(text)
 file=dict(encoding='utf8',content=text,sha256=hashlib.sha256(text.encode()).hexdigest())
 appcases.append(dict(id=ident,domain='web',family=ident,split='validation',variant=i,prompt=f'Build {name} end to end as specified in RFP.md. Read RFP.md and ENVIRONMENT.md first. Deliver a working application, not a plan or snippets. Run and document build/tests; report any remaining limitations honestly.',history=[],files={'RFP.md':file},execution=dict(effort='medium',deadlineMs=3600000,writes=True,web=True,media=False),comparison='implementation'))
 rubric=[dict(id=f,category='features',weight=4,requirement=t) for f,t in features]
 for cat,weight,items in [('build',4,['Clean dependency install/setup/build succeeds','Server health and real UI launch','Documented commands and delivery claims accurate']),('security',4,['Negative tenant/role/session tests pass','Validation,SQL/HTML/CSV andrequest-size protections','Race/idempotency/transactional invariants hold']),('tests',3,['Meaningful automated domain tests execute and pass','Restart persistence and error paths verified']),('ui_ux',3,['Coherent visual hierarchy/readability atdesktop','Mobile390px preservescontent/actions','Keyboard labels/focus/accessibility','Clear error/empty/loading/success states']),('code_quality',2,['Maintainable domain/storage/UI separation','Explicit errors/types/validation','No core stubs/TODO orduplicatedunsafe logic','Clean source/config andno secrets'])]:
  for j,item in enumerate(items,1):rubric.append(dict(id=f'{cat}{j}',category=cat,weight=weight,requirement=item))
 assert sum(x['weight'] for x in rubric)==98
 rubric.append(dict(id='delivery',category='build',weight=2,requirement='All source and required assets present; no externally dependent missing component'))
 appgrades.append(dict(id=ident,title=name,criteria=rubric,scoring='pass=full weight;partial=half only with concrete evidence;fail/unverified=0 demonstrated points; distinguish inability to assess from implementation failure. UI aesthetics require screenshots. No evaluator source repairs.'))
for dirname,data,gold in [('tasks',cases,grades),('apps',appcases,appgrades)]:
 d=root/dirname;d.mkdir(exist_ok=True)
 for name,items in [('prompts.jsonl',data),('grading.jsonl',gold)]: (d/name).write_text(''.join(json.dumps(v,ensure_ascii=False)+'\n' for v in items))
 m=dict(schemaVersion=1,protocol='trust-workflows-v1',caseCount=len(data),createdAt=datetime.datetime.now(datetime.timezone.utc).isoformat(),promptsSha256=hashlib.sha256((d/'prompts.jsonl').read_bytes()).hexdigest(),gradingSha256=hashlib.sha256((d/'grading.jsonl').read_bytes()).hexdigest(),limitations=['Newly authored tasks, not proof of absence from model pretraining.','Raw baseline uses tools and the same Qwen model, not raw-direct.','One first attempt per arm; no tuning on these results.','Live web and production-host contention vary; latency is observational.','Docdex-owned model inference is not included in client token totals; report separately as unmetered.'])
 (d/'manifest.json').write_text(json.dumps(m,indent=2)+'\n')
print('Created',len(cases),'tasks and',len(appcases),'apps')
